local Library = loadstring(game:HttpGet("https://raw.githubusercontent.com/bloodball/-back-ups-for-libs/main/lime"))()

local w = Library:Window("Main")

w:Toggle("Auto Receiving", function(Value)
   _G.Rec = Value
		while _G.Rec do wait()
local args = {
    [1] = "Receiving"
}

game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("PlayerAction"):FireServer(unpack(args))
end
end)

w:Toggle("Auto Spiking", function(Value)
   _G.Test = Value
		while _G.Test do wait()
		local args = {
    [1] = "Spiking"
}

game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("PlayerAction"):FireServer(unpack(args))
end
end)
